#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
#define N (60000*1024)
unsigned char *src, *dst;
int T;
void* worker(void* arg){
    long i=(long)arg;
    size_t chunk=N/T;
    size_t off=i*chunk;
    memcpy(dst+off, src+off, chunk);
    return NULL;
}
int main(){
    src=malloc(N); dst=malloc(N);
    memset(src,0x41,N);
    // memcpy single
    double t0=now();
    for(int r=0;r<5;r++) memcpy(dst,src,N);
    double t1=now();
    printf("memcpy single: %.1f GB/s\n", N*5/(t1-t0)/1e9);
    // memcpy threaded
    for(T=2;T<=12;T*=2){
        pthread_t th[12];
        t0=now();
        for(int r=0;r<5;r++){
            for(long i=0;i<T;i++) pthread_create(&th[i],NULL,worker,(void*)i);
            for(long i=0;i<T;i++) pthread_join(th[i],NULL);
        }
        t1=now();
        printf("memcpy T=%d: %.1f GB/s\n", T, N*5/(t1-t0)/1e9);
    }
    return 0;
}
